<script setup lang="ts">
import type { Row } from '../../../shared/domain';
import { useAddressBook } from '../../../shared/useAddressBook';
import { api } from '../platform';
const props=defineProps<{user:Row|null}>();
const emit=defineEmits<{(event:'join'):void;(event:'chat',row:Row):void;(event:'contact',row:Row):void;(event:'profile'):void}>();
const {query,group,mode,page,loading,busy,error,message,editing,removing,allowed,groups,filtered,pages,visible,load,edit,save}=useAddressBook(()=>props.user,api);
function copy(value:string){uni.setClipboardData({data:value,success:()=>{message.value='已复制联系方式';},fail:()=>{error.value='复制失败，请稍后重试';}});}
function call(value:string){uni.makePhoneCall({phoneNumber:value,fail:()=>{error.value='无法拨打电话，可复制号码后拨打';}});}
function pickGroup(event:any){group.value=groups.value[Number(event.detail.value)]||'全部分组';}
function favorite(event:any){if(editing.value)editing.value.favorite=Boolean(event.detail.value);}
</script>
<template><view class="people-mobile"><view class="title">乡友通讯录</view><view class="intro">有事，找得到人。常用联系人，一处整理。</view><view v-if="error" class="error">{{error}}</view><view v-if="message" class="notice-line">{{message}}</view><view v-if="!allowed" class="empty">通讯录仅向审核通过的会员开放。<button class="primary" @click="emit('join')">{{user?'查看入会状态':'登录／申请加入'}}</button></view><template v-else>
 <view class="people-actions"><button v-for="item in [{id:'all',name:'发现老乡'},{id:'saved',name:'我的联系人'},{id:'favorite',name:'星标常用'}]" :key="item.id" :class="mode===item.id?'primary':'outline'" @click="mode=item.id">{{item.name}}</button></view><input v-model="query" class="search" placeholder="搜索姓名、地区、行业或私人备注" maxlength="80"/><picker :range="groups" :value="Math.max(0,groups.indexOf(group))" @change="pickGroup"><view class="picker-value">分组：{{group}} ▾</view></picker><view class="people-actions"><button class="text-button" :disabled="loading||busy" @click="load">{{loading?'正在加载…':'刷新通讯录'}}</button><button class="text-button" @click="emit('profile')">设置公开偏好</button></view><view class="meta">共 {{filtered.length}} 位 · 分组与备注仅自己可见</view>
 <view v-if="editing" class="panel"><view class="card-title">整理联系人 · {{editing.name}}</view><view class="field"><view class="field-label">分组</view><input v-model="editing.group" maxlength="30" placeholder="例如：活动伙伴"/></view><view class="field"><view class="field-label">私人备注</view><textarea v-model="editing.note" maxlength="300" placeholder="记录认识的场合或沟通事项"/></view><view class="switch-row"><text>设为星标常用</text><switch :checked="editing.favorite" @change="favorite"/></view><view class="people-actions"><button class="primary" :disabled="busy" @click="save()">保存联系人</button><button class="outline" :disabled="busy" @click="editing=null">取消</button></view></view>
 <view v-if="removing" class="panel"><view>确认移除“{{removing.name}}”？分组和私人备注也会移除。</view><view class="people-actions"><button class="primary" :disabled="busy" @click="save(true)">确认移除</button><button class="outline" :disabled="busy" @click="removing=null">保留</button></view></view>
 <view v-for="person in visible" :key="person.id" class="panel person-card"><view class="person-heading"><view class="person-avatar">{{person.available?person.name.slice(0,1):'—'}}</view><view><view class="card-title">{{person.name}} <text v-if="person.favorite">★</text></view><view class="meta">{{person.industry||'乡情相连'}} {{person.saved?'· 已保存':''}}</view></view></view><view v-if="person.hometown||person.district" class="meta">{{person.hometown}} · {{person.district}}</view><view class="prose">{{person.bio||(!person.available?'对方已关闭公开、撤销交换或暂不可联系。':'从一句问候，开始认识。')}}</view><view v-if="person.group||person.note" class="person-note">{{person.group?person.group+' · ':''}}{{person.note}}</view><view v-if="person.phone||person.contact" class="person-contact"><view v-if="person.contact">已交换：{{person.contact}}</view><view v-if="person.phone">电话：{{person.phone}}</view><view class="people-actions"><button v-if="person.phone" class="text-button" @click="call(person.phone)">拨打电话</button><button class="text-button" @click="copy(person.contact||person.phone)">复制联系方式</button></view></view><view class="people-actions"><button class="outline" :disabled="busy" @click="edit(person)">{{person.saved?'编辑备注':'保存联系人'}}</button><button v-if="person.available" class="primary" @click="emit('chat',person)">站内聊聊</button><button v-if="person.available&&!person.contact" class="text-button" @click="emit('contact',person)">申请交换联系方式</button><button v-if="person.saved" class="text-button" :disabled="busy" @click="removing=person">移除</button></view></view>
 <view v-if="!loading&&!error&&!visible.length" class="empty">{{query||group!=='全部分组'?'没有匹配的联系人，请调整筛选。':mode==='all'?'暂时没有可见的老乡资料。':'还没有保存联系人，到“发现老乡”中添加吧。'}}</view><view v-if="pages>1" class="people-actions"><button class="outline" :disabled="page<=1" @click="page--">上一页</button><text>{{page}} / {{pages}}</text><button class="outline" :disabled="page>=pages" @click="page++">下一页</button></view>
</template></view></template>
<style scoped>
.people-actions{display:flex;flex-wrap:wrap;align-items:center;gap:16rpx;margin:24rpx 0}.people-actions button{margin:0;font-size:14px;padding:12rpx 20rpx;line-height:1.6;min-height:44px}.people-mobile .search{margin-bottom:20rpx}.person-card{overflow-wrap:anywhere}.person-heading{display:flex;align-items:center;gap:24rpx}.person-avatar{display:flex;align-items:center;justify-content:center;flex-shrink:0;width:90rpx;height:90rpx;background:var(--ui-soft);color:var(--ui-accent);border-radius:26rpx;font-size:36rpx}.person-note{background:var(--ui-soft);padding:20rpx;border-radius:16rpx;margin:20rpx 0;white-space:pre-wrap;line-height:1.8;font-size:14px}.person-contact{border-top:1px solid var(--ui-line);margin-top:22rpx;padding-top:22rpx;line-height:1.8}.person-card>.people-actions{margin-bottom:0}.people-mobile textarea{width:100%;box-sizing:border-box}
</style>
